#!/usr/bin/env node
// Rebuilds packs/bundle.js from the folders listed in packs/manifest.json.
// The bundle lets the game run when index.html is opened straight from disk (file://),
// where browsers block loading JSON files. Run after adding or editing a folder pack:
//   node tools/bundle-packs.js
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..', 'packs');
const manifest = JSON.parse(fs.readFileSync(path.join(root, 'manifest.json'), 'utf8'));
const out = [];
for (const id of manifest.packs) {
  const dir = path.join(root, id);
  const meta = JSON.parse(fs.readFileSync(path.join(dir, 'pack.json'), 'utf8'));
  const parts = [meta];
  for (const f of meta.include || []) parts.push(JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8')));
  out.push({ id, parts });
  console.log(`bundled ${id} (${parts.length} file${parts.length > 1 ? 's' : ''})`);
}
fs.writeFileSync(path.join(root, 'bundle.js'), '// AUTO-GENERATED by tools/bundle-packs.js. Do not edit; edit the pack folders instead.\nwindow.OMNIVIGIL_BUNDLED_PACKS = ' + JSON.stringify(out) + ';\n');
console.log('wrote packs/bundle.js');
